-- Synthetic fixtures; snapshot date 2026-11-09.
-- The rule versions below are PRE-APPROVED DEMONSTRATION RULES seeded for the applicant-flow stage. They
-- are not official policy. approved_by is a fixed synthetic identifier that stands in for the human review
-- step, which returns (with AI drafting and reviewer screens) in a later stage. Core executes only
-- approved, applicable versions; it never executes a PENDING or REJECTED one.
-- Run with the migration identity, not the runtime role (the runtime role may only insert PENDING versions).
BEGIN;
SET LOCAL search_path TO mahasetu, pg_catalog;
    ON CONFLICT (service_id) DO UPDATE SET display_name = EXCLUDED.display_name;
    ON CONFLICT (provider_id) DO UPDATE SET display_name = EXCLUDED.display_name;
    ON CONFLICT DO NOTHING;
    ON CONFLICT (provider_id, category) DO UPDATE SET label = EXCLUDED.label, description = EXCLUDED.description;
-- Guideline text digested above: Synthetic demonstration guideline for DEMO-PMS, academic year 2026. Not official policy.
COMMIT;
