INSERT INTO rule_versions (rule_id, version, scheme_id, guideline_id, definition, approval_status, approved_by, approved_at) VALUES ('DEMO-INCOME', 1, 'DEMO-PMS', 'DEMO-GUIDELINE-2026', '{"rule_id": "DEMO-INCOME", "rule_name": "Annual income within the demonstration ceiling", "description": "Illustrative only; not official policy.", "scheme_id": "DEMO-PMS", "academic_year": 2026, "evidence_field": "revenue.annual_income", "operator": "LESS_THAN_OR_EQUAL", "expected_value": 250000, "severity": "REQUIRED", "source_document": "Synthetic demonstration guideline", "source_page": 1, "source_section": "Income", "source_text": "For the fixture, annual income may be up to INR 250000.", "effective_from": "2026-01-01", "effective_until": "2030-12-31", "version": 1, "approval_status": "APPROVED", "approved_by": "00000000-0000-4000-8000-0000000000a1", "approved_at": "2026-11-09T00:00:00Z"}'::jsonb, 'APPROVED', '00000000-0000-4000-8000-0000000000a1', '2026-11-09T00:00:00Z') ON CONFLICT (rule_id, version) DO NOTHING;
